const visual = {
  prepare: function (input) {
    var values = [-10, -6, -2, 2, 6, 10];
    var reqs = [];
    for (var i = 0; i < values.length; i++) {
      reqs.push({ kind: 'text', payload: String(values[i]) });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var margin = Math.max(26, Math.min(60, w * 0.1));
    var left = margin;
    var right = w - margin;
    var y = Math.round(h * 0.55);
    var values = [-10, -6, -2, 2, 6, 10];
    var n = values.length;
    var fontSize = Math.max(12, Math.min(20, Math.round(h * 0.045)));
    var tickLen = Math.max(5, Math.round(fontSize * 0.45));
    var labelY = Math.min(h - 4, y + tickLen + 10 + fontSize);
    var axisCmds = visualSdk.polyline([[left, y], [right, y]]);
    var tickCmds = [];
    var labels = [];
    for (var i = 0; i < n; i++) {
      var x = left + (right - left) * i / (n - 1);
      var tick = visualSdk.polyline([[x, y - tickLen], [x, y + tickLen]]);
      for (var j = 0; j < tick.length; j++) {
        tickCmds.push(tick[j]);
      }
      labels.push({
        type: 'label',
        x: x,
        y: labelY,
        text: String(values[i]),
        fontSize: fontSize,
        fill: '#26354a',
        textAnchor: 'middle'
      });
    }
    var children = [
      { type: 'path', pathId: 'axis', stroke: '#26354a', strokeWidth: 2 },
      { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 2 }
    ];
    for (var k = 0; k < labels.length; k++) {
      children.push(labels[k]);
    }
    return {
      schemaVersion: 1,
      sceneId: 'source-axis-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'axis', commands: axisCmds },
        { id: 'ticks', commands: tickCmds }
      ],
      root: { type: 'group', children: children }
    };
  }
};
